@startuml django_project_structure !theme plain skinparam backgroundColor #FEFEFE
title Struktura projektu Django
package "moj_projekt/" { file "manage.py" as manage package "moj_projekt/ (konfiguracja)" { file "__init__.py" as init1 file "settings.py" as settings file "urls.py" as urls_root file "wsgi.py" as wsgi file "asgi.py" as asgi } package "mojapp/ (aplikacja)" { file "__init__.py" as init2 file "admin.py" as admin file "apps.py" as apps file "models.py" as models file "views.py" as views file "urls.py" as urls_app file "forms.py" as forms folder "migrations/" as migrations folder "templates/mojapp/" as templates folder "static/" as static } database "db.sqlite3" as db }
manage ..> settings : konfiguruje models ..> db : migracje views ..> models : QuerySet views ..> templates : render() urls_root --> urls_app : include()
@enduml

@startuml request_lifecycle
!theme plain
skinparam backgroundColor #FEFEFE

title Cykl życia żądania HTTP w Django

start

:Przeglądarka wysyła\nHTTP Request;

:Django Middleware\n(SecurityMiddleware,\nSessionMiddleware...);

:URLconf (urls.py)\ndopasowuje wzorzec URL;

if (wzorzec znaleziony?) then (tak)
    :Wywołanie widoku\n(View Function / CBV);
    :Widok pobiera dane\nz modelu (ORM);
    :Widok przekazuje context\ndo szablonu;
    :Silnik szablonów\ngeneruje HTML;
    :Middleware przetwarza\nodpowiedź;
    :HTTP Response 200 OK;
else (nie)
    :HTTP Response 404 Not Found;
endif

:Przeglądarka wyświetla\nstronę;

stop

@enduml

@startuml migration_flow
!theme plain
skinparam backgroundColor #FEFEFE

title Przepływ migracji w Django

start

:Edytujesz models.py\n(dodajesz/zmieniasz klasy);

:python manage.py\nmakemigrations;

:Django wykrywa różnice\ni tworzy plik migracji\n0001_initial.py;

:python manage.py migrate;

:Django wykonuje SQL\n(CREATE TABLE, ALTER TABLE...)\nna bazie danych;

:db.sqlite3\nzaktualizowana;

stop

note right
  Każda migracja to\n
  "migawka" zmian modeli.\n
  Można cofnąć:\n
  manage.py migrate app 0001
end note

@enduml

@startuml models_erd !theme plain skinparam backgroundColor #FEFEFE
title Diagram ERD – Author i Book (relacja 1:N)
entity "Author" as author { * id : INTEGER <<PK, auto>> -- * first_name : VARCHAR(100) * last_name : VARCHAR(100) birth_year : INTEGER bio : TEXT * created_at : DATETIME }
entity "Book" as book { * id : INTEGER <<PK, auto>> -- * title : VARCHAR(200) * author_id : INTEGER <<FK>> year : INTEGER isbn : VARCHAR(20) description : TEXT * created_at : DATETIME }
author ||--o{ book : "napisał"
@enduml

@startuml orm_queryset !theme plain skinparam backgroundColor #FEFEFE
title ORM Django – QuerySet API
class "QuerySet API" as qs { + all() : QuerySet + filter(**kwargs) : QuerySet + exclude(**kwargs) : QuerySet + get(**kwargs) : Model instance + order_by(*fields) : QuerySet + values(*fields) : ValuesQuerySet + count() : int + first() / last() : Model or None + exists() : bool + select_related(*fields) : QuerySet + prefetch_related(*fields) : QuerySet + create(**kwargs) : Model instance + update(**kwargs) : int + delete() : tuple }
note top of qs QuerySet jest "leniwy" (lazy): SQL jest wykonywany dopiero przy iteracji lub konwersji do listy/slice. end note
@enduml

@startuml url_routing !theme plain skinparam backgroundColor #FEFEFE
title Routing URL w Django
rectangle "bookshelf/urls.py" as root { rectangle "path('admin/', admin.site.urls)" as admin_url rectangle "path('', include('catalog.urls'))" as catalog_include }
rectangle "catalog/urls.py" as catalog { rectangle "path('', views.home)" as home rectangle "path('authors/', views.author_list)" as alist rectangle "path('authors/<int:pk>/', views.author_detail)" as adetail rectangle "path('authors/new/', views.author_create)" as acreate rectangle "path('authors/<int:pk>/edit/', views.author_update)" as aupdate rectangle "path('authors/<int:pk>/delete/', views.author_delete)" as adelete rectangle "path('books/', views.book_list)" as blist rectangle "path('books/<int:pk>/', views.book_detail)" as bdetail }
root --> catalog : include() catalog_include --> catalog
note bottom <int:pk> – konwerter typów: int → liczba całkowita str → dowolny tekst slug → "slug-url" uuid → UUID end note
@enduml

@startuml view_types !theme plain skinparam backgroundColor #FEFEFE
title Rodzaje widoków w Django
abstract class "View (django.views.View)" as View { + dispatch(request, *args, **kwargs) + get(request, *args, **kwargs) + post(request, *args, **kwargs) }
class "ListView" as LV { + model + template_name + context_object_name + queryset + get_queryset() }
class "DetailView" as DV { + model + template_name + pk_url_kwarg = 'pk' }
class "CreateView" as CV { + model + form_class + template_name + success_url }
class "UpdateView" as UV { + model + form_class + template_name + success_url }
class "DeleteView" as DelV { + model + template_name + success_url }
class "FBV\n(Function-Based View)" as FBV { + def view_fn(request, pk=None) + @require_http_methods(["GET","POST"]) }
View <|-- LV View <|-- DV View <|-- CV View <|-- UV View <|-- DelV
note bottom of FBV FBV: prosta, jawna, dobra do nauki. CBV: zwięzła, wielokrotnego użytku przez dziedziczenie. end note
@enduml

