"""Formularze ModelForm dla Author i Book."""
from django import forms
from .models import Author, Book


class AuthorForm(forms.ModelForm):
    class Meta:
        model  = Author
        fields = ['first_name', 'last_name', 'birth_year', 'bio']
        widgets = {
            'bio': forms.Textarea(attrs={'rows': 4}),
            'birth_year': forms.NumberInput(attrs={'min': 1000, 'max': 2100,
                                                   'placeholder': 'np. 1798'}),
        }

    def clean_birth_year(self):
        year = self.cleaned_data.get('birth_year')
        if year is not None and (year < 1000 or year > 2100):
            raise forms.ValidationError("Rok urodzenia musi być między 1000 a 2100.")
        return year


class BookForm(forms.ModelForm):
    class Meta:
        model  = Book
        fields = ['title', 'author', 'year', 'isbn', 'description']
        widgets = {
            'description': forms.Textarea(attrs={'rows': 5}),
        }

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields['author'].queryset = Author.objects.order_by('last_name', 'first_name')
        self.fields['author'].empty_label = "-- Wybierz autora --"

    def clean_year(self):
        year = self.cleaned_data.get('year')
        if year is not None and (year < 1450 or year > 2100):
            raise forms.ValidationError("Rok wydania musi być między 1450 a 2100.")
        return year

    def clean_isbn(self):
        isbn = self.cleaned_data.get('isbn', '').replace('-', '').replace(' ', '')
        if isbn and len(isbn) not in (10, 13):
            raise forms.ValidationError("ISBN musi zawierać 10 lub 13 cyfr.")
        return isbn

{% extends 'catalog/base.html' %}

{% block title %}Usuń autora: {{ author }}{% endblock %}

{% block content %}
<h1>Usuń autora</h1>

<div class="card">
    <p>Czy na pewno chcesz usunąć autora <strong>{{ author }}</strong>?</p>

    {% if books %}
    <div class="alert alert-warning" style="margin-top:.8rem;">
        <strong>⚠️ Uwaga!</strong> Usunięcie autora spowoduje automatyczne usunięcie
        następujących {{ books.count }} książek (ON DELETE CASCADE):
        <ul style="margin-top:.4rem;">
        {% for book in books %}
            <li>{{ book.title }} {% if book.year %}({{ book.year }}){% endif %}</li>
        {% endfor %}
        </ul>
    </div>
    {% endif %}

    <form method="post" style="margin-top:1rem;">
        {% csrf_token %}
        <div class="actions">
            <button type="submit" class="btn btn-danger">Tak, usuń autora{% if books %} i {{ books.count }} książki{% endif %}</button>
            <a href="{% url 'catalog:author_detail' pk=author.pk %}" class="btn btn-secondary">Anuluj</a>
        </div>
    </form>
</div>
{% endblock %}

{% extends 'catalog/base.html' %}

{% block title %}{{ title }}{% endblock %}

{% block content %}
<h1>{{ title }}</h1>

<div class="card">
<form method="post">
    {% csrf_token %}

    {% for field in form %}
    <div class="form-group">
        <label for="{{ field.id_for_label }}">{{ field.label }}{% if field.field.required %} *{% endif %}</label>
        {{ field }}
        {% if field.help_text %}
            <small style="color:#777;">{{ field.help_text }}</small>
        {% endif %}
        {% if field.errors %}
            <ul class="errorlist">
                {% for error in field.errors %}
                    <li>{{ error }}</li>
                {% endfor %}
            </ul>
        {% endif %}
    </div>
    {% endfor %}

    {% if form.non_field_errors %}
    <div class="alert alert-error">
        {% for error in form.non_field_errors %}
            <p>{{ error }}</p>
        {% endfor %}
    </div>
    {% endif %}

    <div class="actions">
        <button type="submit" class="btn btn-primary">Zapisz</button>
        {% if author %}
            <a href="{% url 'catalog:author_detail' pk=author.pk %}" class="btn btn-secondary">Anuluj</a>
        {% else %}
            <a href="{% url 'catalog:author_list' %}" class="btn btn-secondary">Anuluj</a>
        {% endif %}
    </div>
</form>
</div>
{% endblock %}

{% extends 'catalog/base.html' %}

{% block title %}{{ book.title }}{% endblock %}

{% block content %}
<div class="card">
    <h1>{{ book.title }}</h1>

    <p>
        <strong>Autor:</strong>
        <a href="{% url 'catalog:author_detail' pk=book.author.pk %}">{{ book.author }}</a>
    </p>
    {% if book.year %}
        <p><strong>Rok wydania:</strong> {{ book.year }}</p>
    {% endif %}
    {% if book.isbn %}
        <p><strong>ISBN:</strong> {{ book.isbn }}</p>
    {% endif %}
    {% if book.description %}
        <p style="margin-top:.6rem;"><strong>Opis:</strong><br>{{ book.description|linebreaks }}</p>
    {% endif %}
    <p style="margin-top:.6rem; color:#999; font-size:.85rem;">
        Dodano: {{ book.created_at|date:"d.m.Y H:i" }}
    </p>

    <div class="actions">
        <a href="{% url 'catalog:book_update' pk=book.pk %}" class="btn btn-warning">Edytuj</a>
        <a href="{% url 'catalog:book_delete' pk=book.pk %}" class="btn btn-danger">Usuń</a>
        <a href="{% url 'catalog:author_detail' pk=book.author.pk %}" class="btn btn-secondary">
            ← {{ book.author }}
        </a>
        <a href="{% url 'catalog:book_list' %}" class="btn btn-secondary">Lista książek</a>
    </div>
</div>
{% endblock %}

